```json
{
  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_k8s_pod_name, count(*) n, min(time)::VARCHAR t0, max(time)::VARCHAR t1, max(value) mx FROM abnormal_metrics WHERE attr_k8s_pod_name ILIKE 'profile%' GROUP BY ALL",
          "claim": "Profile pod emits only k8s.container.ready=0 in the abnormal window, from 17:21:15 to 17:24:45, then stops emitting."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name pod, max(value) mx, min(time)::VARCHAR t0, max(time)::VARCHAR t1 FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name ILIKE 'profile%' GROUP BY ALL",
          "claim": "The profile pod's restart counter climbs to 6 during the incident window."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) n FROM abnormal_traces WHERE service_name='profile' OR attr_k8s_pod_name ILIKE 'profile%' GROUP BY ALL",
          "claim": "No profile service spans exist in the abnormal window, whereas the normal window has 2172."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE span_name LIKE 'profile.Profile/%' OR (service_name='frontend' AND span_name='HTTP /hotels') GROUP BY ALL",
          "claim": "All frontend calls to profile.Profile/GetProfiles error (1017/1017), and all frontend HTTP /hotels server spans fail with 500s (660/660)."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) c FROM abnormal_logs WHERE level='ERROR' GROUP BY ALL",
          "claim": "Frontend logs 'Get profiles failed' at ERROR level 1140 times during the incident, with no other service logging errors."
        }
      ]
    }
  ]
}
```

